const WebSocket = require('ws');
const rtCorpFeed = require('./event').rtCorpFeed;
const utils = require('./utils');

const socketCloseStates = [2, 3];

let connection = null;
let disconnectConnection = false;

let user;
let pwd;
let port;
let connectionUrl = '';

let lastHeartBeatTime = 0;
let hearbeatCheckerCalled = false;
let heartbeatMessage;
const reconnectLogs = [];
let t;

const { reconnectionTime } = utils;

module.exports.rtCorpConnect = (
    username,
    password,
    userPort = 9092,
    heartbeat = 1
) => {
    disconnectConnection = false;
    hearbeatCheckerCalled = false;
    heartbeatMessage = heartbeat === 1 ? true : false;
    user = username;
    pwd = password;
    port = userPort;
    connectionUrl = `wss://corp.truedata.in:${port}?user=${user}&password=${pwd}`;
    initiateConnection();
}

module.exports.rtCorpDisconnect = () => {
    if (connection) {
        disconnectConnection = true;
        for (let i = 0; i < 20; i++) {
            clearInterval(t);
        }
        closeConnection();
        connection = null;
    } else {
        console.log('Calling rtDisconnect before the websocket connection is established');
    }
};

module.exports.isCorpSocketConnected = () => {
    return connection !== null && !socketCloseStates.includes(connection.readyState);
};

const initiateConnection = () => {
    if (!connection || (connection && socketCloseStates.includes(connection.readyState))) {
        console.log("Connecting...");
        console.log(connectionUrl);
        try {
            connection = new WebSocket(connectionUrl);

            connection.onopen = socketonopen;
            connection.onerror = socketonerror;
            connection.onmessage = socketonmessage;
            connection.onclose = socketonclose;

            return true;
        } catch (error) {
            console.log(error);
            setInterval(initiateConnection, reconnectionTime);
            return false;
        }
    } else {
        console.log("Already Connected...");
    }
}

function socketonopen() {
    console.log("Corporate WebSocket Connection Established!");
}

function socketonerror(error) {
    console.log("Corporate WebSocket Error: ", error.message);
}

function socketonmessage(e) {
    var jsonObj = JSON.parse(e.data);

    if(jsonObj.success){
        switch (jsonObj.message) {
            case "TrueData Real Time Corporate Annoucements Service":
                if (reconnectLogs.length === 0) console.log(jsonObj);
                if (!hearbeatCheckerCalled) {
                    hearbeatChecker();
                    hearbeatCheckerCalled = true;
                }
                break;
    
            case 'HeartBeat':
                const { message, timestamp } = jsonObj;
                heartbeatMessage && console.log('Message: ' + message + ' Time: ' + timestamp);
                rtCorpFeed.emit('heartbeat', { Message: message, Timestamp: timestamp });
                lastHeartBeatTime = Date.now();
                break;
    
            default:
                rtCorpFeed.emit('message', jsonObj)
                break;
        }
    }else{
        rtCorpFeed.emit('message', jsonObj);
    }
}

function hearbeatChecker() {
    t = setInterval(() => {
        const checkerHeartBeat = Date.now() - lastHeartBeatTime;
        if (checkerHeartBeat > 15000) {
            closeConnection();
            hearbeatCheckerCalled = false;
            const reconnectLog = `Auto Reconnect Initiated @ ${new Date().toLocaleTimeString()}`;
            reconnectLogs.push(reconnectLog);
            console.log(reconnectLog);
            for (let i = 0; i < 20; i++) {
                clearInterval(t);
            }
        }
    }, 20000);
}

function socketonclose(e) {
    console.log("Disconnected Corporate WebSocket!");
    if (!disconnectConnection) {
        setTimeout(initiateConnection, reconnectionTime);
    }
}

function closeConnection() {
    connection.close();
}